import json
from pathlib import Path

subject = 'site:sqlite-statement-diagnostic'
digest = '704c6ce7ad25ad66c08e1426c3cb5d43595df839866d978c6a7ec828396a1759'
source = Path('world/pages/reviews-1.json')
result = {'subject': subject, 'digest': digest, 'source': str(source), 'matches': []}

def records(value):
    if isinstance(value, dict):
        if 'subject' in value and 'digest' in value:
            yield value
        for item in value.values():
            yield from records(item)
    elif isinstance(value, list):
        for item in value:
            yield from records(item)

if source.is_file():
    rows = list(records(json.loads(source.read_text(encoding='utf-8'))))
    result['review_records_read'] = len(rows)
    keys = ('seq', 'reviewer', 'verdict', 'host_turn', 'host_provider', 'at')
    result['matches'] = [{key: row.get(key) for key in keys} for row in rows if row['subject'] == subject and row['digest'] == digest]
    result['matches'].sort(key=lambda row: (row['seq'] or 0, row['at'] or 0))
    result['latest_verdict_in_page'] = result['matches'][-1]['verdict'] if result['matches'] else None
else:
    result['source_state'] = 'unavailable_in_executor_inputs'
result['deployment_gate'] = 'Host must verify publishing-provider and writer independence. This readback cannot establish eligibility.'
output = Path('products/distribution/sqlite-quote-intake/review-readback.json')
output.parent.mkdir(parents=True, exist_ok=True)
output.write_text(json.dumps(result, indent=2) + '\n', encoding='utf-8')
print(output.read_text(encoding='utf-8'))
